  Lemma w4e_d0 : 0 <= DST /\ DST + dcap <= ATOP /\ (DST + dcap <= 0x7fff7000 \/ 0x10007fff8000 <= DST).
Proof using AH DC DJ2 DJ3 DSTF cbs sp tl.
  try clear SLOW; try clear FAP; try clear FAST.
  pose proof (@ATOP_lo rc) as HA.
  destruct DSTF as [[-> ->]|(pb & HB)]; [lia|].
  pose proof (AI_block AI L RNG st LB m0 pb DST dcap AH HB) as (D1 & (C2 & C3 & C4 & C5) & _).
  unfold ablk, AIMG_HI, KLS in C2. lia.
Qed.

  (* [comment removed for export] *)
  Lemma w4e_appW : appW DW.
Proof using All.
  pose proof w4e_d0 as (D1 & D2 & D3). pose proof (@ATOP_lo rc) as HA.
  unfold appW, KLOW, KHIGH. apply Forall_cons; [|apply Forall_cons; [|apply Forall_nil]]; cbn [fst snd]; lia.
Qed.

