  (* [comment removed for export] *)
  Lemma w4e_unp : forall m, munch DW m0 m ->
    unpoisoned m DT (DT + DTL) /\ (0 < n -> unpoisoned m SS (SS + n)).
Proof using AH DC DJ2 DJ3 DSTF HDT LOA LOS S16 SPT SRCB cbs tl.
  try clear SLOW; try clear FAP; try clear FAST.
  intros m MU.
  pose proof w4e_sp as (S1 & S2 & S3 & S4). pose proof (@ATOP_lo rc) as HA. pose proof (@ATOP_hi rc) as HA2.
  pose proof w4e_d0 as (D1 & D2 & D3).
  pose proof (hb_unpoisoned AI L RNG st LB m0 pdt DT DTL AH HDT) as (U1 & _ & _ & K1 & _).
  unfold ablk, AIMG_HI, KLS in K1.
  split.
  - eapply unpoisoned_munch; [exact U1 | exact MU |]. cbn [disjoint_from]. rewrite !shad_div. unfold ASHOFF. lia.
  - intros Hn. destruct (SRCB Hn) as (p & HB & B1 & B2).
    pose proof (hb_unpoisoned AI L RNG st LB m0 p SBL (SBH - SBL) AH HB) as (U2 & _ & _ & K2 & _).
    unfold ablk, AIMG_HI, KLS in K2.
    eapply unpoisoned_munch; [eapply unpoisoned_sub; [exact U2 | lia | lia] | exact MU |].
    cbn [disjoint_from]. rewrite !shad_div. unfold ASHOFF. lia.
Qed.

  (* [comment removed for export] *)
  Lemma w4e_aheap : forall mm, munch DW m0 mm -> wmono bsegs m0 mm -> AHEAP AI L RNG st LB mm.
Proof using AH DC DSTF LOA LOS SPT cbs src tl.
  try clear SLOW; try clear FAP; try clear FAST.
  intros mm MU WM. pose proof w4e_sp as SPB.
  destruct DSTF as [[E1 E2] | [pb HBo]].
  - eapply (AI_frame AI _ _ _ _ m0 mm [(lo, SP)]); [exact AH | eapply munch_weaken; [|exact MU] | exact WM |].
    + intros x Hx. cbn [outside] in *. destruct Hx as [Hx _]. split; [exact Hx | split; [lia | exact I]].
    + apply Forall_cons; [|apply Forall_nil]; cbn [fst snd]; unfold aclient_range, aclient_app_range.
      left. left. lia.
  - eapply (AI_frame AI); [exact AH | exact MU | exact WM |].
    apply Forall_cons; [|apply Forall_cons; [|apply Forall_nil]]; cbn [fst snd]; unfold aclient_range, aclient_app_range.
    + left. left. lia.
    + right. left. exists (HB pb DST dcap). split; [exact HBo|]. cbn. lia.
Qed.

  Lemma w4e_magree : forall mm, munch DW m0 mm -> wmono bsegs m0 mm ->
    magree bsegs (fun a => aclient_addr CI LB SP a /\ ~ (DST <= a < DST + dcap)) m0 mm.
Proof using AH DC LOA cbs src tl.
  try clear SLOW; try clear FAP; try clear FAST.
  intros mm MU WM. apply (munch_magreeA DW m0 mm); [exact MU | exact WM |].
  intros a [CA ND]. cbn [outside]. split; [| split; [exact ND | exact I]].
  pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
  destruct CA as [S | [R | [B | (a' & A' & E)]]].
  - lia.
  - destruct R as (iv & IN & R1 & R2). pose proof (AI_aci_img AI iv IN) as HI. unfold ABase.AIMG_HI in HI. lia.
  - destruct B as (b & IN & B1 & B2). pose proof (AI_block_bounds AI _ _ _ _ _ b AH IN) as (BB1 & BB2 & BB3).
    unfold ABase.AIMG_HI in BB1. lia.
  - subst a. unfold shad, ASHOFF. rewrite ?Z.shiftr_div_pow2 by lia.
    assert (A'B : 0 <= a' < 2^47).
    { destruct A' as [A1 | [(iv & IN & R1 & R2) | (cls & A & k & IN & F1 & F2)]].
      - lia.
      - pose proof (AI_aci_img AI iv IN). pose proof (AI_aci_lo AI iv IN). unfold ABase.AIMG_HI in *. lia.
      - pose proof (AI_block_bounds AI _ _ _ _ _ _ AH IN) as (BB1 & BB2 & BB3). cbn [ab_addr ab_size] in BB1, BB2, BB3.
        unfold ABase.AIMG_HI in *. lia. }
    Z.div_mod_to_equations. lia.
Qed.

  (* [comment removed for export] *)
  Lemma w4e_epi : forall mm (t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6 xra : word),
    stk bsegs mm lo (SP + -104) -> rw_cells bsegs mm (SP + -104) FRS ->
    mem_inv bsegs mm -> munch DW m0 mm -> wmono bsegs m0 mm ->
    evtF bsegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7
                                 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6) FR (Z_to_bv 64 AW4_EPI) fc None mm (seg_rom bsegs)).
Proof using All.
  intros mm t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6 xra ST FRC MI MU WM.
  pose proof w4e_sp as SPB.
  unfold AW4_EPI.
  do 15 zstep.
  release_frame FRC ST (bv_unsigned sp).
  apply evtF_done. unfold huf_dec_postA.
  do 15 eexists. exists mm.
  split; [reflexivity|].
  exact (conj MI (conj ST (conj (w4e_magree mm MU WM) (w4e_aheap mm MU WM)))).
Qed.

  Lemma w4e_W4F : forall mm fr mid j256 j296 j336,
    bytes_at bsegs m0 SS (map (Z_to_bv 8) src) -> bytes_at bsegs m0 (DT + 4) cbs ->
    bytes_at bsegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 0; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    stk bsegs mm lo (SP + -480) -> rw_cells bsegs mm (SP + -480) fr -> cells_size fr = 104%nat ->
    rw_cells bsegs mm (SP + -376) mid -> cells_size mid = 152%nat -> rw_cells bsegs mm (SP + -224) [CB 40 j256] ->
    rw_cells bsegs mm (SP + -184) [CB 40 j296] -> rw_cells bsegs mm (SP + -144) [CB 40 j336] ->
    rw_cells bsegs mm (SP + -104) FRS -> mem_inv bsegs mm -> munch DW m0 mm -> wmono bsegs m0 mm ->
    W4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT mtl tl lo src cbs mm
        fr mid [CB 40 j256] [CB 40 j296] [CB 40 j336].
Proof using AH BYS DC DJ1 DJ2 DJ3 DSTF HDT LCB LOA LOS MTL NSM SPT SRCB TLM.
  try clear SLOW; try clear FAP; try clear FAST.
  intros mm fr mid j256 j296 j336 SRC CBS DTH ST F0 FS M1 MS L1 L2 L3 FRA MI MU WM.
  pose proof w4e_blocks as (B1 & B2 & B3 & B4 & _). pose proof w4e_sp as SPB. pose proof (@ATOP_lo rc) as HA.
  unfold KXGoM.apart in DJ3.
  unfold W4F.
  replace (SP + -480 + 104) with (SP + -376) by lia. replace (SP + -480 + 256) with (SP + -224) by lia.
  replace (SP + -480 + 296) with (SP + -184) by lia. replace (SP + -480 + 336) with (SP + -144) by lia.
  refine (conj _ (conj _ (conj _ (conj _ (conj ST (conj F0 (conj FS (conj M1 (conj MS (conj L1 (conj eq_refl
          (conj L2 (conj eq_refl (conj L3 (conj eq_refl (conj FRA (conj MI (conj MU WM)))))))))))))))))).
  - destruct (w4e_out mm WM) as [[E1 E2] | Hb]; [|exact Hb].
    exists []. rewrite E1, E2. unfold u8arr, bytes_at, wr_at. cbn. repeat split; try lia; intros; lia.
  - exact (w4e_src mm SRC MU).
  - eapply bytes_at_transport; [exact CBS | exact MU |]. cbn [disjoint_from]. lia.
  - eapply bytes_at_transport; [exact DTH | exact MU |]. cbn [disjoint_from length]. lia.
Qed.

  (* [comment removed for export] *)
  Definition FAW (b0 b1 b2 b3 : Z) : list word :=
    let l1 := jt_len src 0 in let l2 := jt_len src 2 in let l3 := jt_len src 4 in
    [ Z_to_bv 64 (SS + 6 + l1 - 8); Z_to_bv 64 (SS + 6 + l1 + l2 - 8); Z_to_bv 64 (SS + 6 + l1 + l2 + l3 - 8);
      Z_to_bv 64 (SS + n - 8);
      Z_to_bv 64 DST; Z_to_bv 64 (DST + seg); Z_to_bv 64 (DST + 2 * seg); Z_to_bv 64 (DST + 3 * seg);
      Z_to_bv 64 b0; Z_to_bv 64 b1; Z_to_bv 64 b2; Z_to_bv 64 b3;
      Z_to_bv 64 (DT + 4); Z_to_bv 64 SS; Z_to_bv 64 (DST + dcap);
      Z_to_bv 64 (SS + 6); Z_to_bv 64 (SS + 6 + l1); Z_to_bv 64 (SS + 6 + l1 + l2); Z_to_bv 64 (SS + 6 + l1 + l2 + l3) ].

  (* [comment removed for export] *)
  Ltac w4wsrd A i :=
    lazymatch goal with W : u64arr bsegs ?mm A ?ws |- evtF _ _ _ (MS _ _ _ _ _ ?mm _) =>
      pose proof (u64arr_read bsegs mm A ws i _ _ W eq_refl ltac:(lia) ltac:(unfold wa; f_equal; lia)) end.

  (* [comment removed for export] *)
  Lemma w4_entry : forall (t0 t1 t2 a6 a7 t3 t4 t5 t6 : word) (flags : Z),
    bytes_at bsegs m0 SS (map (Z_to_bv 8) src) -> bytes_at bsegs m0 (DT + 4) cbs ->
    bytes_at bsegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 0; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    stk bsegs m0 lo SP -> mem_inv bsegs m0 -> 0 <= flags < 64 ->
    evtF bsegs RNG POST (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 DST) (Z_to_bv 64 dcap) (Z_to_bv 64 SS) (Z_to_bv 64 n)
                                 (Z_to_bv 64 DT) (Z_to_bv 64 flags) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                            FR (Z_to_bv 64 AHUF_DX1_4X) fc None m0 (seg_rom bsegs)).
Proof using All.
  intros t0 t1 t2 a6 a7 t3 t4 t5 t6 flags SRC CBS DTH ST MI FL.
  pose proof w4e_sp as SPB. pose proof (AI_rtcells AI _ _ _ _ _ AH) as RTC.
  pose proof RTC as RTC0. unfold artcells in RTC0.
  destruct RTC0 as (_ & GOT & _ & _ & SHB & _).
  pose proof w4e_blocks as (B1 & B2 & B3 & B4 & B5 & B6). pose proof w4e_d0 as (D1 & D2 & D3).
  pose proof (fun mm fr mid j256 j296 j336 => w4e_W4F mm fr mid j256 j296 j336 SRC CBS DTH) as PK.
  pose proof (fun m MU' => w4e_src m SRC MU') as WSRC.
  pose proof (conj SPB (conj B1 (conj B2 (conj B4 (conj B5 (conj D1 (conj D2 DC))))))) as CF.
  pose proof (hb_unpoisoned AI L RNG st LB m0 pdt DT DTL AH HDT) as (_ & _ & _ & _ & _ & RDT & RDS & _).
  rewrite shlen_nshad, nshad_div in RDS. pose proof TOK as (TL1 & _).
  pose proof (munch_refl DW m0) as MU. pose proof (wmono_refl bsegs m0) as WM.
  unfold AHUF_DX1_4X.
  zstep.
  carve_frame 104%nat ST. carve_frame 40%nat ST. carve_frame 40%nat ST. carve_frame 40%nat ST.
  carve_frame 152%nat ST. carve_frame 104%nat ST.
  do 22 zstep.
  zstep. if_cases K; zify_cond K.
  2: { zstep. eapply SLOW. apply PK. all: first [eassumption | reflexivity]. }
  do 7 zstep.
  zstep. if_cases BrA; zify_cond BrA.
  2: { w4chk BrA CF. }
  do 3 zstep.
  zstep. if_cases BrB; zify_cond BrB.
  2: (assert (DP : 0 < dcap) by lia;
      pose proof (conj DP CF) as CF1;
      do 2 zstep;
      zstep; if_cases BrC; zify_cond BrC; [ | w4chk BrC CF1 ];
      zstep; if_cases BrD; zify_cond BrD; [ | w4chk BrD CF1 ];
      zstep;
      zstep; if_cases BrE; zify_cond BrE; [ | w4chk BrE CF1 ]).
  all: do 9 zstep.
  all: eapply evtF_cut; [eapply (FAP RNG) with (A := SP + -376) (DST := DST) (dcap := dcap) (S := SS) (DT := DT)
      (mtl := mtl) (tt := 0) (tl := tl) (mtl' := mtl) (src := src) (lo := lo) (rstk := rstk) | ].
  all: try (first [eassumption | reflexivity]).
  all: try (exact (WSRC _ MU)).
  all: try (exact (AI_rtcells AI _ _ _ _ _ (w4e_aheap _ MU WM))).
  all: try (exact (w4e_rclean _ MU WM)).
  all: try (exact (proj2 (w4e_unp _ MU))).
  all: try (eapply unpoisoned_sub; [exact (proj1 (w4e_unp _ MU)) | lia | lia]).
  all: try (rewrite unsigned_lit by lia).
  all: try eassumption.
  all: try (eapply rng_sub; [exact WSK | | ]; unfold AHUF_FAST_ARGS_STACK; lia).
  all: try (eapply rng_sub; [exact RDT | lia | lia]).
  all: try (eapply rng_sub; [exact RDS | lia | Z.div_mod_to_equations; lia]).
  all: try (clear - SP16 B1 B2 B3 B4 B5 B6 D1 D2 SPB MTL TLM TL1 S16 RLO RHI LOS DC;
            unfold AIMG_HI, AHUF_FAST_ARGS_STACK in *; Z.div_mod_to_equations; lia).
  all: try (intros Hn; destruct (SRCB Hn) as (p & HB & SB1 & SB2);
     pose proof (hb_unpoisoned AI L RNG st LB m0 p SBL (SBH - SBL) AH HB) as (_ & A16 & _ & _ & _ & RS1 & RS2 & _);
     rewrite shlen_nshad, nshad_div in RS2; split;
     [eapply rng_sub; [exact RS1 | lia | lia]
     | eapply rng_sub; [exact RS2 | rewrite !shad_div; Z.div_mod_to_equations; lia
                       | rewrite !shad_div, nshad_div; Z.div_mod_to_equations; lia]]).
  all: intros ms' HP.
  all: destruct HP as (xt0 & xt1 & xt2 & xa1 & xa2 & xa3 & xa4 & xa5 & xa6 & xa7 & xt3 & xt4 & xt5 & xt6 & r & mm &
         EQ & MU1 & WM1 & MI1 & ST1 & (ja1 & JA) & RR); subst ms'.
  all: rewrite ret_pc_even by lia.
  all: rewrite unsigned_lit in ST1, MU1 by lia.
  all: assert (MU2 : munch DW m0 mm) by (eapply munch_trans; [eassumption | ];
         apply (fun H => munch_weaken _ _ _ _ H MU1); unfold sub_fp; intros x; cbn [outside];
         unfold AHUF_FAST_ARGS_STACK; intros (X1 & X2 & _); repeat split; lia).
  all: assert (WM2 : wmono bsegs m0 mm) by (eapply wmono_trans; eassumption).
  all: match goal with H : rw_cells _ _ SPF _ |- _ => rename H into F0 end.
  all: match goal with H : rw_cells _ _ (SP + -224) _ |- _ => rename H into L1 end.
  all: match goal with H : rw_cells _ _ (SP + -184) _ |- _ => rename H into L2 end.
  all: match goal with H : rw_cells _ _ (SP + -144) _ |- _ => rename H into L3 end.
  all: match goal with H : rw_cells _ _ (SP + -104) _ |- _ => rename H into FRA end.
  all: eapply (rw_cells_transport bsegs _ _ mm) in F0; [ | exact MU1 | exact WM1 | cbn [disjoint_from cells_size csize Nat.add]; lia].
  all: eapply (rw_cells_transport bsegs _ _ mm) in L1; [ | exact MU1 | exact WM1 | cbn [disjoint_from cells_size csize Nat.add]; lia].
  all: eapply (rw_cells_transport bsegs _ _ mm) in L2; [ | exact MU1 | exact WM1 | cbn [disjoint_from cells_size csize Nat.add]; lia].
  all: eapply (rw_cells_transport bsegs _ _ mm) in L3; [ | exact MU1 | exact WM1 | cbn [disjoint_from cells_size csize Nat.add]; lia].
  all: eapply (rw_cells_transport bsegs _ _ mm) in FRA; [ | exact MU1 | exact WM1 | cbn [disjoint_from cells_size csize Nat.add]; lia].
  all: destruct RR as [-> | [-> | [-> OK]]].
  3: { exfalso; destruct OK as (_ & _ & _ & _ & _ & _ & DP' & _).
       apply Bool.andb_false_iff in BrB; destruct BrB as [X|X]; apply Z.ltb_ge in X; lia. }
  5: { destruct OK as (TL11 & N10 & J0 & J2 & J4 & JS & DP' & SEG & b0 & b1 & b2 & b3 & BB0 & BB1 & BB2 & BB3 &
         MB0 & MB1 & MB2 & MB3 & FAC).
       apply (rw_cells_split_CB bsegs mm SPF [] 40 _ _ [8;8;8;8;8]%nat) in F0; [| reflexivity].
       cbn [app mk_CB_cells] in F0. repeat c8ifyF F0. absj F0.
       eapply FAST; [apply PK | ..]; first [eassumption | reflexivity]. }
  1,3: (w4to AW4_SLOW;
        eapply SLOW; apply PK; first [eassumption | reflexivity]).
  all: w4to AW4_EPI.
  all: release_frame F0 ST1 (SP + -376).
  all: match goal with H : rw_cells _ ?m (SP + -376) _ |- evtF _ _ _ (MS _ _ _ _ _ ?m _) => release_frame H ST1 (SP + -224) end.
  all: release_frame L1 ST1 (SP + -184). all: release_frame L2 ST1 (SP + -144). all: release_frame L3 ST1 (SP + -104).
  all: eapply w4e_epi; first [eassumption].
Qed.

